import Combine
import UIKit

/// Keeps the phone app visible behind a black surface. This does not lock iOS.
@MainActor
final class BlackScreenController: ObservableObject {
    @Published private(set) var isEnabled = false
    private var screen: UIScreen?
    private var previousBrightness: CGFloat = 0
    private var previousIdleTimerDisabled = false

    func enable() {
        guard !isEnabled, UIApplication.shared.applicationState == .active,
              let phoneScene = UIApplication.shared.connectedScenes
                .compactMap({ $0 as? UIWindowScene })
                .first(where: { $0.session.role == .windowApplication && $0.activationState == .foregroundActive })
        else { return }

        screen = phoneScene.screen
        previousBrightness = phoneScene.screen.brightness
        previousIdleTimerDisabled = UIApplication.shared.isIdleTimerDisabled
        UIApplication.shared.isIdleTimerDisabled = true
        phoneScene.screen.brightness = 0
        isEnabled = true
    }

    func disable() {
        guard isEnabled else { return }
        screen?.brightness = previousBrightness
        UIApplication.shared.isIdleTimerDisabled = previousIdleTimerDisabled
        screen = nil
        isEnabled = false
    }
}

import SwiftUI
import UIKit

enum CoroStyle {
    static let accent = Color(red: 1, green: 0.47, blue: 0.34)
    static let background = Color(red: 0.055, green: 0.065, blue: 0.08)
    static let card = Color(red: 0.09, green: 0.105, blue: 0.13)
}

struct MainView: View {
    @ObservedObject var session: SessionController
    @ObservedObject var auth: SpotifyAuth
    @State private var settings = false
    @StateObject private var blackScreen = BlackScreenController()
    @Environment(\.scenePhase) private var scenePhase

    var body: some View {
        ZStack {
            if blackScreen.isEnabled {
                BlackScreenView(onExit: blackScreen.disable)
            } else {
                mainContent
            }
        }
        .statusBarHidden(blackScreen.isEnabled)
        .persistentSystemOverlays(blackScreen.isEnabled ? .hidden : .automatic)
        .sheet(isPresented: $settings) { SettingsView(session: session, auth: auth) }
        .sheet(item: $auth.page, onDismiss: { auth.dismissAuthorization() }) { page in
            SafariView(url: page.url).ignoresSafeArea()
        }
        .onChange(of: session.running) { _, running in
            if !running { blackScreen.disable() }
        }
        .onChange(of: scenePhase) { _, phase in
            if phase != .active { blackScreen.disable() }
        }
        .onReceive(NotificationCenter.default.publisher(for: UIApplication.willResignActiveNotification)) { _ in
            // Restore immediately, including before a manual lock or app switch.
            blackScreen.disable()
        }
        .onDisappear { blackScreen.disable() }
    }

    private var mainContent: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 28) {
                HStack(alignment: .center) {
                    VStack(alignment: .leading, spacing: 4) {
                        Text("Coro").font(.system(size: 40, weight: .bold, design: .rounded))
                        Text("LETRAS A TU RITMO").font(.caption2.weight(.semibold)).tracking(2).foregroundStyle(.secondary)
                    }
                    Spacer()
                    Button { settings = true } label: {
                        Image(systemName: "slider.horizontal.3").font(.title3).frame(width: 48, height: 48)
                            .background(CoroStyle.card, in: Circle())
                    }
                    .accessibilityLabel("Ajustes")
                    .disabled(auth.isAuthorizing || session.starting)
                }

                HStack(spacing: 8) {
                    Circle().fill(session.isDemo ? .orange : (session.running ? CoroStyle.accent : .gray)).frame(width: 7, height: 7)
                    Text(session.isDemo && session.running ? "DEMOSTRACIÓN" : (session.running ? "SESIÓN ACTIVA" : "LISTO CUANDO TÚ QUIERAS"))
                        .font(.caption.weight(.semibold)).tracking(1)
                }
                .foregroundStyle(.secondary)

                VStack(alignment: .leading, spacing: 20) {
                    HStack(alignment: .top, spacing: 12) {
                        Image(systemName: "music.note").font(.title3).foregroundStyle(CoroStyle.accent)
                            .frame(width: 44, height: 44).background(CoroStyle.accent.opacity(0.12), in: RoundedRectangle(cornerRadius: 14))
                        VStack(alignment: .leading, spacing: 5) {
                            Text(session.track?.title ?? "Tu próxima canción")
                                .font(.headline).lineLimit(2)
                            Text(session.track?.artists.joined(separator: ", ") ?? "La música sigue en Spotify")
                                .font(.subheadline).foregroundStyle(.secondary).lineLimit(2)
                        }
                    }
                    Rectangle().fill(.white.opacity(0.08)).frame(height: 1)
                    Text(session.line)
                        .font(.system(size: 30, weight: .semibold, design: .rounded))
                        .foregroundStyle(session.running ? CoroStyle.accent : .white)
                        .frame(maxWidth: .infinity, minHeight: 130, alignment: .leading)
                        .accessibilityLabel("Línea actual: \(session.line)")
                    if !session.nextLine.isEmpty {
                        Text(session.nextLine).font(.title3).foregroundStyle(.secondary)
                            .accessibilityLabel("Siguiente línea: \(session.nextLine)")
                    }
                    if !session.notice.isEmpty {
                        Text(session.notice).font(.footnote).foregroundStyle(.secondary)
                    }
                }
                .padding(24)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(CoroStyle.card, in: RoundedRectangle(cornerRadius: 28))

                VStack(spacing: 12) {
                    if session.running {
                        Button { blackScreen.enable() } label: {
                            Label("Pantalla negra", systemImage: "moon.fill")
                                .frame(maxWidth: .infinity).padding(.vertical, 10)
                        }
                        .buttonStyle(.borderedProminent).controlSize(.large).foregroundStyle(.black)
                        Text("Deja Coro abierto y el iPhone desbloqueado. No pulses el botón lateral. Toca dos veces la pantalla negra para volver; se restaurará el brillo anterior.")
                            .font(.footnote).foregroundStyle(.secondary)
                            .frame(maxWidth: .infinity, alignment: .leading)
                        Button { session.stop() } label: {
                            Label("Detener sesión", systemImage: "stop.fill").frame(maxWidth: .infinity).padding(.vertical, 10)
                        }
                        .buttonStyle(.bordered).controlSize(.large)
                    } else if auth.isConnected {
                        Button { Task { await session.start() } } label: {
                            Label(session.starting ? "Preparando…" : "Iniciar letras", systemImage: "play.fill")
                                .frame(maxWidth: .infinity).padding(.vertical, 10)
                        }
                        .buttonStyle(.borderedProminent).controlSize(.large).foregroundStyle(.black)
                        .disabled(session.starting)
                    } else {
                        Button {
                            if auth.clientID.isEmpty { settings = true }
                            else { Task { await auth.connect() } }
                        } label: {
                            Label(auth.isAuthorizing ? "Conectando…" : "Conectar Spotify", systemImage: "link")
                                .frame(maxWidth: .infinity).padding(.vertical, 10)
                        }
                        .buttonStyle(.borderedProminent).controlSize(.large).foregroundStyle(.black)
                        .disabled(auth.isAuthorizing)
                    }
                    if !session.running {
                        Button("Ver demostración de 45 segundos") { Task { await session.start(demo: true) } }
                            .font(.subheadline).padding(.vertical, 8)
                            .disabled(session.starting || auth.isAuthorizing)
                    }
                    Link(destination: session.track?.spotifyURL ?? URL(string: "https://open.spotify.com/")!) {
                        Label("Reproducción en Spotify", systemImage: "arrow.up.right")
                            .font(.footnote.weight(.medium)).foregroundStyle(.secondary)
                    }
                }

                if let message = session.message ?? auth.message {
                    Text(message).font(.footnote).foregroundStyle(.secondary)
                        .padding(16).frame(maxWidth: .infinity, alignment: .leading)
                        .background(.white.opacity(0.04), in: RoundedRectangle(cornerRadius: 16))
                }

                VStack(alignment: .leading, spacing: 8) {
                    Label("En CarPlay", systemImage: "car.side").font(.subheadline.weight(.semibold))
                    Text("Inicia la sesión, abre el panel de CarPlay y activa Pantalla negra en Coro. La letra permanece junto a las otras apps del panel. Mantén Coro abierto: bloquear el iPhone o cambiar de app puede congelar las letras.")
                        .font(.footnote).foregroundStyle(.secondary)
                    Text("Letras: LRCLIB · La disponibilidad depende de cada canción.")
                        .font(.caption2).foregroundStyle(.secondary)
                }
                .padding(.bottom, 8)
            }
            .padding(24)
        }
        .background(CoroStyle.background)
    }
}

import SwiftUI

struct SettingsView: View {
    @ObservedObject var session: SessionController
    @ObservedObject var auth: SpotifyAuth
    @Environment(\.dismiss) private var dismiss
    @State private var clientID = ""
    @State private var error: String?

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField("Client ID de Spotify", text: $clientID)
                        .textInputAutocapitalization(.never).autocorrectionDisabled()
                        .font(.system(.footnote, design: .monospaced))
                        .disabled(session.running)
                    if let error { Text(error).foregroundStyle(.red).font(.footnote) }
                    Button("Guardar Client ID") {
                        do { try auth.configure(clientID: clientID); error = nil; dismiss() }
                        catch { self.error = error.localizedDescription }
                    }
                    .disabled(session.running || clientID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    Text("Solo se necesita el identificador público de tu app personal. Nunca pegues tu contraseña ni el Client Secret.")
                        .font(.footnote).foregroundStyle(.secondary)
                } header: { Text("Spotify") }

                Section("Desfase de la letra") {
                    Stepper(value: $session.offset, in: -10...10, step: 0.25) {
                        Text(String(format: "%+.2f segundos", session.offset)).monospacedDigit()
                    }
                    Text("Positivo: la letra aparece antes. Negativo: después. Ajusta con una canción que conozcas.")
                        .font(.footnote).foregroundStyle(.secondary)
                    Button("Restablecer a cero") { session.offset = 0 }
                }

                Section("Pantalla negra") {
                    Text("Inicia las letras y pulsa Pantalla negra en la pantalla principal. Coro bajará el brillo y evitará el bloqueo automático mientras este modo esté activo. El iPhone sigue desbloqueado.")
                        .font(.footnote).foregroundStyle(.secondary)
                    Text("Toca dos veces para volver. Al salir del modo, cambiar de app o terminar la sesión se restauran el brillo y el bloqueo automático anteriores.")
                        .font(.footnote).foregroundStyle(.secondary)
                }

                Section("Segundo plano experimental") {
                    Toggle("Mantener la sesión activa", isOn: $session.keepAlive).disabled(session.running)
                    Text("Reproduce silencio local mezclado con Spotify para intentar mantener Coro activo fuera de la app. No garantiza que las letras avancen con el iPhone bloqueado. Pantalla negra no necesita esta opción. Cámbiala con la sesión detenida.")
                        .font(.footnote).foregroundStyle(.secondary)
                    Text("La sesión termina al desconectar CarPlay o tras dos minutos sin reproducción.")
                        .font(.footnote).foregroundStyle(.secondary)
                }

                Section("Preparación inicial") {
                    Link("Abrir Spotify for Developers", destination: URL(string: "https://developer.spotify.com/dashboard")!)
                    Text("Redirect URI exacta:").font(.footnote)
                    Text(LoopbackCallback.redirect).font(.system(.caption, design: .monospaced)).textSelection(.enabled)
                    Text("En la app de Spotify for Developers selecciona Web API y guarda esta dirección. Después copia aquí el Client ID. Usa la misma cuenta Premium.")
                        .font(.footnote).foregroundStyle(.secondary)
                }

                Section("Tus datos") {
                    Text("El acceso de Spotify se guarda en el llavero de este iPhone. Solo consultamos la reproducción. Para buscar letras se envían a LRCLIB título, artista, álbum y duración. No hay cuenta de Coro, anuncios ni analítica.")
                        .font(.footnote).foregroundStyle(.secondary)
                    if auth.isConnected {
                        Button("Desconectar Spotify y borrar acceso", role: .destructive) { session.disconnect() }
                    }
                    Link("Administrar permisos en Spotify", destination: URL(string: "https://www.spotify.com/account/apps/")!)
                    Link("Fuente de letras: LRCLIB", destination: URL(string: "https://lrclib.net/")!)
                }
                Section {
                    Text("Coro 0.1.2 · Prototipo para uso personal. No está afiliado a Spotify ni a Apple.")
                        .font(.footnote).foregroundStyle(.secondary)
                }
            }
            .navigationTitle("Ajustes")
            .toolbar { ToolbarItem(placement: .confirmationAction) { Button("Listo") { dismiss() } } }
            .onAppear { clientID = auth.clientID }
        }
        .preferredColorScheme(.dark).tint(CoroStyle.accent)
    }
}

import SwiftUI
import WidgetKit
import ActivityKit

@main
struct CoroWidgetBundle: WidgetBundle {
    var body: some Widget { CoroLiveActivity() }
}

struct CoroLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: CoroAttributes.self) { context in
            LyricsCard(context: context)
                .activityBackgroundTint(.black)
                .activitySystemActionForegroundColor(.white)
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.leading) {
                    Label(context.state.isDemo ? "DEMO" : "Coro", systemImage: "music.note")
                        .font(.caption.weight(.semibold)).foregroundStyle(.orange)
                }
                DynamicIslandExpandedRegion(.trailing) {
                    Image(systemName: context.state.isPlaying ? "waveform" : "pause.fill")
                }
                DynamicIslandExpandedRegion(.bottom) {
                    VStack(alignment: .leading, spacing: 5) {
                        Text(context.isStale ? "Esperando a Spotify…" : context.state.line)
                            .font(.headline).lineLimit(2)
                        if !context.isStale {
                            Text(context.state.nextLine).font(.caption).foregroundStyle(.secondary).lineLimit(1)
                        }
                    }
                }
            } compactLeading: {
                Image(systemName: "music.note").foregroundStyle(.orange)
            } compactTrailing: {
                Text(context.isStale ? "…" : (context.state.isDemo ? "DEMO" : "Coro")).font(.caption2)
            } minimal: {
                Image(systemName: "music.note").foregroundStyle(.orange)
            }
            .keylineTint(.orange)
        }
        .supplementalActivityFamilies([.small, .medium])
    }
}

struct LyricsCard: View {
    @Environment(\.activityFamily) private var family
    let context: ActivityViewContext<CoroAttributes>
    private let coral = Color(red: 1, green: 0.52, blue: 0.39)

    var body: some View {
        if family == .small {
            // CarPlay has very little height. Give it all to the current lyric.
            ViewThatFits(in: .vertical) {
                compactLyric(size: 18)
                compactLyric(size: 16)
                compactLyric(size: 14)
                Text(visibleLine)
                    .font(.system(size: 14, weight: .semibold, design: .rounded))
                    .lineLimit(3)
                    .minimumScaleFactor(0.85)
            }
            .foregroundStyle(coral)
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
            .padding(6)
        } else {
            fullCard
        }
    }

    private var visibleLine: String {
        context.isStale ? "Esperando a Spotify…" : context.state.line
    }

    private func compactLyric(size: CGFloat) -> some View {
        Text(visibleLine)
            .font(.system(size: size, weight: .bold, design: .rounded))
            .fixedSize(horizontal: false, vertical: true)
            .frame(maxWidth: .infinity, alignment: .leading)
    }

    private var fullCard: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 5) {
                Image(systemName: "music.note").foregroundStyle(coral)
                Text(context.state.isDemo ? "DEMO" : context.state.title).lineLimit(1)
                Spacer(minLength: 0)
                if !context.state.isPlaying { Image(systemName: "pause.fill") }
            }
            .font(.caption2.weight(.semibold)).foregroundStyle(.white.opacity(0.65))
            Text(visibleLine)
                .font(.title3.weight(.semibold))
                .foregroundStyle(coral)
                .lineLimit(2)
                .minimumScaleFactor(0.8)
                .frame(maxWidth: .infinity, alignment: .leading)
            if !context.isStale, !context.state.nextLine.isEmpty {
                Text(context.state.nextLine)
                    .font(.subheadline)
                    .foregroundStyle(.white.opacity(0.6)).lineLimit(1)
            }
            if !context.state.notice.isEmpty {
                Text(context.state.notice).font(.caption2).foregroundStyle(.white.opacity(0.5)).lineLimit(1)
            }
        }
        .padding(16)
    }
}
